    ctx.fillRect(x, centerY - height/2, width, height);

    // Draw scale markings
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 1;
    ctx.font = '10px Arial, sans-serif';
    ctx.textAlign = 'right';

    // VS scale: -2000 to +2000 fpm
    const maxVS = 2000;
    const pixelsPerFPM = height / (2 * maxVS);

    // Draw tick marks and labels
    const vsMarks = [-2000, -1000, -500, 0, 500, 1000, 2000];
    vsMarks.forEach(vs => {
        const y = centerY - (vs * pixelsPerFPM);

        if (y >= centerY - height/2 && y <= centerY + height/2) {
            const tickLength = (vs === 0) ? 8 : 4;

            // Draw tick mark
            ctx.beginPath();
            ctx.moveTo(x, y);
            ctx.lineTo(x + tickLength, y);
            ctx.stroke();

            // Draw labels for major marks
            if (Math.abs(vs) >= 500 || vs === 0) {
                const label = vs === 0 ? '0' : (Math.abs(vs) >= 1000 ? (vs/1000).toString() : (vs/100).toString());
                ctx.fillText(label, x - 2, y + 3);
            }
        }
    });

    // Draw current VS indicator
    const currentVSY = centerY - (verticalSpeed * pixelsPerFPM);

    // Clamp to visible area
    if (currentVSY >= centerY - height/2 && currentVSY <= centerY + height/2) {
        // Draw VS pointer (triangle)
        ctx.fillStyle = COLORS.GREEN_NORMAL;
        ctx.strokeStyle = COLORS.GREEN_NORMAL;
        ctx.lineWidth = 2;

        ctx.beginPath();
        if (verticalSpeed > 50) {
            // Climb indicator (up triangle)
            ctx.moveTo(x + width/2, currentVSY - 4);
            ctx.lineTo(x + 2, currentVSY + 2);
            ctx.lineTo(x + width - 2, currentVSY + 2);
        } else if (verticalSpeed < -50) {
            // Descent indicator (down triangle)
            ctx.moveTo(x + width/2, currentVSY + 4);
            ctx.lineTo(x + 2, currentVSY - 2);
            ctx.lineTo(x + width - 2, currentVSY - 2);
        } else {
            // Minimal VS - small diamond
            ctx.moveTo(x + width/2, currentVSY - 2);
            ctx.lineTo(x + 2, currentVSY);
            ctx.lineTo(x + width/2, currentVSY + 2);
            ctx.lineTo(x + width - 2, currentVSY);
        }
        ctx.closePath();
        ctx.fill();
